import { Group, PlaneGeometry, MeshStandardNodeMaterial, Mesh, DirectionalLight, AmbientLight } from 'three/webgpu';
import { uv, vec3, mix, sin, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. Stage / Backdrop Plane to prevent Flat Void & create engineered gradient
  const bgGeo = new PlaneGeometry(8.5, 6.5);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.4
  });

  // TSL Gradient for the backdrop with a subtle metallic sweep
  const uvNode = uv();
  const gradColor = mix(
    vec3(0.04, 0.04, 0.06), // Very deep dark surface-ink
    vec3(0.12, 0.12, 0.16), // Slightly lighter machined metal hue
    uvNode.y.add(sin(uvNode.x.mul(3.14159).add(time.mul(0.15))).mul(0.1))
  );
  bgMat.colorNode = gradColor;

  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.z = -0.4;
  group.add(backdrop);

  // 2. High-End Direct/Rim Lighting (Node-Local)
  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(2, 3, 2);
  group.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.8);
  localRimLight.position.set(-3, -2, 1);
  group.add(localRimLight);

  const localFillLight = new AmbientLight(colors.surface, 0.5);
  group.add(localFillLight);

  // 3. The Main Textured Card Plane
  // Aspect ratio 512:320 -> 1.6. Width 4.0, Height 2.5
  const cardGeo = new PlaneGeometry(4.0, 2.5);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.25,
    metalness: 0.5,
    transparent: true,
    opacity: 0.05 // starts transparent, transitions on load or image resolution
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0.05);
  group.add(cardMesh);

  // Load the card texture using cached textureLoader
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((texture) => {
        cardMat.map = texture;
        cardMat.opacity = 1.0;
        cardMat.needsUpdate = true;
      })
      .catch((err) => {
        console.error('Failed to load card texture:', err);
      });
  }

  // 4. Subtle Border Frame for the premium "machined-metal" look
  const borderGeo = new PlaneGeometry(4.08, 2.58);
  const borderMat = new MeshStandardNodeMaterial({
    color: colors.paper,
    roughness: 0.1,
    metalness: 0.9
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = 0.01;
  group.add(borderMesh);

  // Soft subtle hover / idle breath animation
  const tl = gsap.timeline({ repeat: -1, yoyo: true });
  tl.to(cardMesh.position, {
    z: 0.08,
    duration: 3.5,
    ease: 'power1.inOut'
  });

  // Apply primitives if any exist
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const inst = ctx.primitives[primitive.name](group, primitive.params);
        activePrimitives.push(inst);
      }
    });
  }

  // Clean-up protocol
  group.userData = {
    cleanup() {
      tl.kill();
      activePrimitives.forEach((p) => {
        if (typeof p.cleanup === 'function') {
          p.cleanup();
        }
      });
      cardGeo.dispose();
      cardMat.dispose();
      bgGeo.dispose();
      bgMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
    }
  };

  return group;
}
